export const iconUrls: Record<string, string> = {
  astron: _astron,
  atlascloud: _atlascloud,
  bailing: _bailing,
  byteplus: _byteplus,
  cherryin: _cherryin,
  etok: _etok,
  hermes: _hermes,
  huoshan: _huoshan,
  nekocode: _nekocode,
  qiniu: _qiniu,
  sub2api: _sub2api,
  unity2: _unity2,
};

export const iconList = [
  ...Object.keys(icons),
  ...Object.keys(iconUrls),
].sort();

export function getIcon(name: string): string {
  return icons[name.toLowerCase()] || "";
}

export function getIconUrl(name: string): string {
  return iconUrls[name.toLowerCase()] || "";
}

export function hasIcon(name: string): boolean {
  const key = name.toLowerCase();
  return key in icons || key in iconUrls;
}

export function isUrlIcon(name: string): boolean {
  return name.toLowerCase() in iconUrls;
}

export { getIconMetadata, isTileIcon } from "./metadata";
